import { useState, useMemo, useEffect } from 'react';
import Navbar from '../components/Navbar';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import SummaryCard from '../components/SummaryCard';
import InvestmentForm from '../components/InvestmentForm';
import InvestmentList from '../components/InvestmentList';
import Tabs from '../components/Tabs';
import styles from './Dashboard.module.css';

const Dashboard = () => {
  // Cargar datos iniciales desde localStorage
  const loadInitialData = (key, defaultValue) => {
    try {
      const saved = localStorage.getItem(key);
      return saved ? JSON.parse(saved) : defaultValue;
    } catch (error) {
      console.error('Error loading data from localStorage:', error);
      return defaultValue;
    }
  };

  const [transactions, setTransactions] = useState(() => 
    loadInitialData('transactions', [])
  );
  const [investments, setInvestments] = useState(() => 
    loadInitialData('investments', [])
  );
  const [activeTab, setActiveTab] = useState(0);
  const [initialBalance] = useState(310000); // Fondo inicial fijo

  // Guardar datos en localStorage cuando cambien
  useEffect(() => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('investments', JSON.stringify(investments));
  }, [investments]);

  // Calcular el fondo actual según la lógica solicitada
  const currentBalance = useMemo(() => {
    const totalInvested = investments.reduce(
      (sum, inv) => sum + parseFloat(inv.initialCost || 0),
      0
    );
    const remainingAfterInvestment = initialBalance - totalInvested;

    const totalProfit = investments.reduce(
      (sum, inv) => sum + (parseFloat(inv.salePrice || 0) - parseFloat(inv.initialCost || 0)),
      0
    );

    const totalSpentOnPurchases = totalInvested;

    return remainingAfterInvestment + Math.max(0, totalProfit) + totalSpentOnPurchases;
  }, [investments, initialBalance]);

  // Calcular resúmenes para el dashboard
  const [totalIncome, totalExpenses] = useMemo(() => {
    const incomes = transactions
      .filter(t => t.type === 'income')
      .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

    const expenses = transactions
      .filter(t => t.type === 'expense')
      .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

    return [incomes, expenses];
  }, [transactions]);

  const netProfit = totalIncome - totalExpenses;

  // Función para agregar transacción regular
  const handleAddTransaction = (transaction) => {
    const newTransaction = { 
      ...transaction, 
      amount: parseFloat(transaction.amount),
      date: new Date().toISOString().split('T')[0],
      id: Date.now() // Agregar ID único
    };
    setTransactions(prev => [...prev, newTransaction]);
  };

  // Función para agregar inversión
  const handleAddInvestment = (investment) => {
    const newInvestment = {
      ...investment,
      id: Date.now(), // Agregar ID único
      initialCost: parseFloat(investment.initialCost),
      salePrice: parseFloat(investment.salePrice),
      purchaseDate: new Date().toISOString().split('T')[0]
    };
    
    setInvestments(prev => [...prev, newInvestment]);

    // Registrar costo inicial como gasto
    const costTransaction = {
      id: Date.now(),
      description: `Compra de laptop (${investment.brand})`,
      amount: newInvestment.initialCost,
      type: 'expense',
      date: newInvestment.purchaseDate,
      relatedInvestment: true
    };
    
    setTransactions(prev => [...prev, costTransaction]);

    // Si hay precio de venta, registrar la ganancia/pérdida
    if (newInvestment.salePrice > 0) {
      const profit = newInvestment.salePrice - newInvestment.initialCost;
      const profitTransaction = {
        id: Date.now(),
        description: profit > 0 
          ? `Ganancia por venta de laptop (${investment.brand})` 
          : `Pérdida por venta de laptop (${investment.brand})`,
        amount: Math.abs(profit),
        type: profit > 0 ? 'income' : 'expense',
        date: new Date().toISOString().split('T')[0],
        relatedInvestment: true
      };
      
      setTransactions(prev => [...prev, profitTransaction]);
    }
  };

  // Función para eliminar transacción
  const handleDeleteTransaction = (id) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  // Función para eliminar inversión
  const handleDeleteInvestment = (id) => {
    setInvestments(prev => prev.filter(inv => inv.id !== id));
    // También eliminar transacciones relacionadas
    setTransactions(prev => prev.filter(t => 
      !t.relatedInvestment || t.description.includes(investments.find(inv => inv.id === id)?.brand || '')
    ));
  };

  // Función para limpiar todos los datos
  const handleClearAllData = () => {
    if (window.confirm('¿Estás seguro de que quieres borrar todos los datos? Esta acción no se puede deshacer.')) {
      setTransactions([]);
      setInvestments([]);
      localStorage.removeItem('transactions');
      localStorage.removeItem('investments');
    }
  };

  // Definir pestañas
  const tabs = ['Resumen', 'Transacciones', 'Inversiones'];

  return (
    <div>
      <Navbar />
      <div className={styles.dashboard}>
        <h1>Control de Negocios</h1>
        <button 
          onClick={handleClearAllData} 
          className={styles.clearButton}
        >
          Limpiar Todos los Datos
        </button>
        
        <Tabs tabs={tabs} activeTab={activeTab} onTabChange={setActiveTab} />

        {activeTab === 0 && (
          <div className={styles.summaryCard}>
            <SummaryCard
              totalIncome={totalIncome}
              totalExpenses={totalExpenses}
              balance={netProfit}
              currentBalance={currentBalance}
              initialBalance={initialBalance}
              totalInvested={investments.reduce((sum, inv) => sum + parseFloat(inv.initialCost || 0), 0)}
              totalProfit={investments.reduce(
                (sum, inv) => sum + (parseFloat(inv.salePrice || 0) - parseFloat(inv.initialCost || 0)),
                0
              )}
            />
          </div>
        )}

        {activeTab === 1 && (
          <div className={styles.transactionSection}>
            <h2>Transacciones</h2>
            <TransactionForm onAddTransaction={handleAddTransaction} />
            <TransactionList 
              transactions={transactions} 
              onDeleteTransaction={handleDeleteTransaction}
            />
          </div>
        )}

        {activeTab === 2 && (
          <div className={styles.investmentSection}>
            <InvestmentForm onAddInvestment={handleAddInvestment} />
            <InvestmentList
              investments={investments}
              onDeleteInvestment={handleDeleteInvestment}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
